import{_ as e,o as a,c as o,a4 as r}from"./chunks/framework.Dayh6OL6.js";const k=JSON.parse('{"title":"Docker","description":"Docker","frontmatter":{"title":"Docker","showArticleMetadata":true,"sort":3,"date":"2024-08-15T00:00:00.000Z","description":"Docker"},"headers":[],"relativePath":"programmer/docker.md","filePath":"pages/programmer/docker/index.md"}'),t={name:"programmer/docker.md"},i=r('<h1 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h1><p><code>Docker</code> 属于 Linux 容器的一种封装，<code>Docker</code> 将应用程序与该程序的依赖，打包在一个文件里面。运行这个文件，就会生成一个虚拟容器。程序在这个虚拟容器里运行，就好像在真实的物理机上运行一样。</p><h1 id="解决痛点" tabindex="-1">解决痛点 <a class="header-anchor" href="#解决痛点" aria-label="Permalink to &quot;解决痛点&quot;">​</a></h1><ol><li>不用担心环境问题</li><li>资源占用少</li><li>部署方便</li></ol><h1 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h1><p>（1）提供一次性的环境。比如，本地测试他人的软件、持续集成的时候提供单元测试和构建的环境。</p><p>（2）提供弹性的云服务。因为 <code>Docker</code> 容器可以随开随关，很适合动态扩容和缩容。</p><p>（3）组建微服务架构。通过多个容器，一台机器可以跑多个服务，因此在本机就可以模拟出微服务架构。</p><h1 id="学习流程" tabindex="-1">学习流程 <a class="header-anchor" href="#学习流程" aria-label="Permalink to &quot;学习流程&quot;">​</a></h1><ol><li>docker 安装</li><li>docker 镜像（image）</li><li>运行 docker 容器</li><li>自定义容器镜像（dockerfile+image）</li></ol>',10),c=[i];function l(d,n,s,h,_,p){return a(),o("div",null,c)}const u=e(t,[["render",l]]);export{k as __pageData,u as default};
